package glitch

import data.glitch_lib
import future.keywords.in

sensitive_keys := {"password", "secret", "token", "api_key", "db_password", "connection_string", "keystore_password", "truststore_password", "sha512_password", "passwd", "pwd", "admin_password", "key"}

is_hardcoded_string(value) {
    value.ir_type == "String"
    not glitch_lib.has_variable_reference(value)
}

has_sensitive_key(key) {
    is_string(key)
    lower_key := lower(key)
    sensitive_keys[lower_key]
}

find_hardcoded_passwords(node, path) = results {
    results := {{"path": path, "element": node}}
    node.ir_type == "String"
    is_hardcoded_string(node)
    count(path) > 0
    last_key := path[count(path) - 1]
    has_sensitive_key(last_key)
} else = results {
    node.ir_type == "Hash"
    results := {r |
        pair := node.value[_]
        key := pair.key
        val := pair.value
        new_path := array.concat(path, [key])
        r := find_hardcoded_passwords(val, new_path)
    }
} else = results {
    node.ir_type == "Array"
    results := {r |
        elem := node.value[_]
        r := find_hardcoded_passwords(elem, path)
    }
} else = results {
    results := set()
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    var := glitch_lib.all_variables(parent)[_]
    results := find_hardcoded_passwords(var.value, [var.name])
    count(results) > 0
    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Hard-coded password in IaC script - Avoid using hard-coded passwords and secrets. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attr := glitch_lib.all_attributes(parent)[_]
    results := find_hardcoded_passwords(attr.value, [attr.name])
    count(results) > 0
    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded password in IaC script - Avoid using hard-coded passwords and secrets. (CWE-259)"
    }
}
